def affected(l) -> bool:
    n = len(l)
    if n < 2:
        return False
    def comparable(a, b):
        try:
            a > b
            a < b
            return True
        except Exception:
            return False
    if not all(comparable(l[i], l[i + 1]) for i in range(n - 1)):
        return False  # both versions raise on the adjacent comparisons
    if not comparable(l[0], l[-1]):
        return True  # mutant compares l[0] with l[-1] and raises; original does not
    inc = all(l[i] <= l[i + 1] for i in range(n - 1))
    dec = all(l[i] >= l[i + 1] for i in range(n - 1))
    inc_m = all(l[i] <= l[i - 1] for i in range(n - 1))
    return (not dec) and (inc != inc_m)
